public final class SMPGameplay implements CommandExecutor, Listener {
 private final ESNDataStore data; private final Map<UUID,Integer> mined=new HashMap<>(), kills=new HashMap<>();
 public SMPGameplay(ESNDataStore d){data=d;}
 @Override public boolean onCommand(CommandSender s,Command c,String l,String[] a){
  if(!(s instanceof Player p)){s.sendMessage("Players only.");return true;}
  switch(c.getName().toLowerCase()){
   case "menu" -> openMenu(p);
   case "shop" -> openShop(p);
   case "crates" -> openCrates(p);
   case "daily" -> daily(p);
   case "quests" -> quests(p);
   case "leaderboard" -> leaderboard(p);
   case "warps" -> warps(p);
  } return true;
 }
 public void openMenu(Player p){Inventory i=Bukkit.createInventory(null,27,ChatColor.GOLD+"ESN SMP Menu");i.setItem(10,b(Material.EMERALD,ChatColor.GREEN+"Server Shop"));i.setItem(12,b(Material.ENDER_CHEST,ChatColor.LIGHT_PURPLE+"Loot Crates"));i.setItem(14,b(Material.WRITABLE_BOOK,ChatColor.AQUA+"Daily & Quests"));i.setItem(16,b(Material.COMPASS,ChatColor.YELLOW+"Warps"));p.openInventory(i);}
 public void openShop(Player p){openShop(p,1);} public void openShop(Player p,int page){page=Math.max(1,Math.min(20,page));Inventory i=Bukkit.createInventory(null,54,ChatColor.DARK_GREEN+"ESN Server Shop • "+page+"/20");Material[][] mats={{Material.COOKED_BEEF,Material.GOLDEN_CARROT,Material.BREAD,Material.COOKED_CHICKEN,Material.COOKED_PORKCHOP,Material.PUMPKIN_PIE,Material.HONEY_BOTTLE},{Material.OAK_LOG,Material.SPRUCE_LOG,Material.STONE,Material.COBBLESTONE,Material.GLASS,Material.BRICKS,Material.QUARTZ_BLOCK},{Material.COAL,Material.IRON_INGOT,Material.GOLD_INGOT,Material.REDSTONE,Material.LAPIS_LAZULI,Material.DIAMOND,Material.EMERALD},{Material.ENDER_PEARL,Material.BLAZE_ROD,Material.GHAST_TEAR,Material.SLIME_BALL,Material.PHANTOM_MEMBRANE,Material.EXPERIENCE_BOTTLE,Material.OBSIDIAN},{Material.GUNPOWDER,Material.STRING,Material.BONE,Material.ROTTEN_FLESH,Material.SPIDER_EYE,Material.LEATHER,Material.FEATHER},{Material.TOTEM_OF_UNDYING,Material.NETHERITE_SCRAP,Material.ENCHANTED_GOLDEN_APPLE,Material.ELYTRA,Material.SHULKER_SHELL,Material.HEART_OF_THE_SEA,Material.NAUTILUS_SHELL}};int[][] amounts={{16,16,16,16,16,8,8},{32,32,64,64,32,32,16},{16,8,8,32,32,1,4},{8,4,2,16,4,16,16},{32,32,32,32,16,16,32},{1,1,1,1,2,1,8}};long[][] prices={{120,180,80,120,140,160,180},{160,180,120,100,300,350,500},{180,240,300,160,180,500,450},{600,800,900,400,700,450,500},{250,180,180,120,200,240,180},{12000,5000,25000,30000,4000,3500,1600}};String[] cats={"Food & Farming","Building Blocks","Ores & Economy","Adventure","Mob Drops","Rare & Endgame","Woodworks","Redstone","Nether","End","Brewing","Decoration","Stoneworks","Colored Blocks","Ocean","Nature","Lighting","Transportation","Utility","Collector"};i.setItem(4,b(Material.EMERALD,ChatColor.GOLD+cats[page-1],List.of(ChatColor.GRAY+"Page "+page+" of 20",ChatColor.YELLOW+"140 total shop listings")));for(int n=0;n<7;n++){Material m=shopMaterial(page,n);int amount=shopAmount(page,n);long price=shopPrice(page,n);i.setItem(19+n,b(m,ChatColor.GREEN+"Buy "+amount+" "+pretty(m),List.of(ChatColor.GOLD+""+price+" ESN Coins",ChatColor.YELLOW+"Click to purchase")));}nav(i,page,20);p.openInventory(i);}
 public void openCrates(Player p){openCrates(p,1);} public void openCrates(Player p,int page){page=Math.max(1,Math.min(5,page));Inventory i=Bukkit.createInventory(null,54,ChatColor.DARK_PURPLE+"ESN Loot Crates • "+page+"/5");if(page==1){for(int n=0;n<ExtendedCrates.LOW.length;n++){String[] r=Arrays.stream(ExtendedCrates.pool(false,n)).map(x->ChatColor.stripColor(x.getItemMeta().getDisplayName())).toArray(String[]::new);i.setItem(19+n,b(new Material[]{Material.OAK_PLANKS,Material.STONE,Material.COPPER_INGOT,Material.BRICK,Material.IRON_INGOT,Material.EMERALD,Material.OBSIDIAN}[n],ChatColor.GREEN+"Tier "+(n+1)+" • "+ExtendedCrates.LOW[n]+" Crate",crateLoreKey(ExtendedCrates.LOW[n]+" Crate Key","11.11%",r)));}}else if(page==2){i.setItem(10,b(Material.ENDER_CHEST,ChatColor.WHITE+"Tier 6 • ESN Crate",List.of(ChatColor.GRAY+"Requires: ESN Crate Key",ChatColor.DARK_GRAY+"--- Possible Rewards ---",ChatColor.WHITE+"Titan Blade • Voidbreaker • Titan Chestplate • Void Crown",ChatColor.WHITE+"Netherite • Diamonds • Golden Apples • XP Bottles")));i.setItem(11,b(Material.END_CRYSTAL,ChatColor.AQUA+"Tier 7 • Celestial Crate",crateLore("8.33%","Celestial Saber","Celestial Reaver","Celestial Excavator","Celestial Halo","Celestial Aegis","Celestial Greaves","Celestial Walkers","Celestial Bow","Reaper Scythe","Poseidon Wrath","Dragonspine Bow","Phantom Repeater")));String[] names={"Infernal","Storm","Shadow","Frost","Solar","Abyssal","Dragonlord"};Material[] icons={Material.BLAZE_POWDER,Material.LIGHTNING_ROD,Material.ECHO_SHARD,Material.PACKED_ICE,Material.SUNFLOWER,Material.RESPAWN_ANCHOR,Material.DRAGON_HEAD};for(int n=0;n<7;n++)i.setItem(12+n,b(icons[n],ChatColor.GOLD+"Tier "+(8+n)+" • "+names[n]+" Crate",List.of(ChatColor.YELLOW+"Click to open",ChatColor.GRAY+"Hover the existing progression gear in /esnitems")));i.setItem(19,b(Material.HEAVY_CORE,ChatColor.DARK_AQUA+"Tier 15 • Eternal Crate",crateLoreKey("Eternal Crate Key","11.11%","Eternal Dominion","Eternal Ruin","Eternal Excavator","Eternal Terraformer","Eternal Harvester","Eternal Crown","Eternal Aegis","Eternal Legguards","Eternal Walkers")));}else if(page==3){for(int n=0;n<10;n++){String[] r=Arrays.stream(MythicCrates.pool(n)).map(x->ChatColor.stripColor(x.getItemMeta().getDisplayName())).toArray(String[]::new);i.setItem(19+n,b(new Material[]{Material.NETHER_STAR,Material.CRYING_OBSIDIAN,Material.FEATHER,Material.HEART_OF_THE_SEA,Material.NETHERITE_BLOCK,Material.BLACK_DYE,Material.BEACON,Material.CLOCK,Material.END_CRYSTAL,Material.DRAGON_EGG}[n],ChatColor.GOLD+"Tier "+(16+n)+" • "+MythicCrates.TIERS[n]+" Crate",crateLoreKey(MythicCrates.TIERS[n]+" Crate Key","11.11%",r)));}}else if(page==4){for(int n=0;n<6;n++){String[] r=Arrays.stream(ExtendedCrates.pool(true,n)).map(x->ChatColor.stripColor(x.getItemMeta().getDisplayName())).toArray(String[]::new);i.setItem(20+n,b(new Material[]{Material.FIREWORK_STAR,Material.ENDER_EYE,Material.NETHER_STAR,Material.TOTEM_OF_UNDYING,Material.END_CRYSTAL,Material.DRAGON_EGG}[n],ChatColor.DARK_PURPLE+"Tier "+(26+n)+" • "+ExtendedCrates.HIGH[n]+" Crate",crateLoreKey(ExtendedCrates.HIGH[n]+" Crate Key","11.11%",r)));}}else{for(int n=6;n<ExtendedCrates.HIGH.length;n++){String[] r=Arrays.stream(ExtendedCrates.pool(true,n)).map(x->ChatColor.stripColor(x.getItemMeta().getDisplayName())).toArray(String[]::new);i.setItem(19+(n-6),b(new Material[]{Material.BEACON,Material.RESPAWN_ANCHOR,Material.HEAVY_CORE,Material.NETHERITE_BLOCK}[n-6],ChatColor.DARK_RED+"ULTIMATE • "+ExtendedCrates.HIGH[n]+" Crate",crateLoreKey(ExtendedCrates.HIGH[n]+" Crate Key","11.11%",r)));}}nav(i,page,5);p.openInventory(i);}
 @EventHandler public void click(InventoryClickEvent e){String t=e.getView().getTitle();if(!t.startsWith(ChatColor.GOLD+"ESN SMP")&&!t.startsWith(ChatColor.DARK_GREEN+"ESN Server")&&!t.startsWith(ChatColor.DARK_PURPLE+"ESN Loot"))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p))return;int s=e.getRawSlot();if(t.contains("SMP Menu")){if(s==10)openShop(p);else if(s==12)openCrates(p);else if(s==14){p.closeInventory();daily(p);quests(p);}else if(s==16){p.closeInventory();warps(p);}return;}if(t.contains("Server Shop")){int page=page(t);if(s==45&&page>1){openShop(p,page-1);return;}if(s==53&&page<20){openShop(p,page+1);return;}if(s>=19&&s<=25)shopBuy(p,page,s-19);return;}if(t.contains("Loot Crates")){int page=page(t);if(s==45&&page>1){openCrates(p,page-1);return;}if(s==53&&page<5){openCrates(p,page+1);return;}if(page==1&&s>=19&&s<26)openExtendedCrate(p,false,s-19);else if(page==2){if(s==10)openCrate(p);else if(s==11)openCelestialCrate(p);else if(s>=12&&s<=18)openTierCrate(p,s+8);else if(s==19)openEternalCrate(p);}else if(page==3&&s>=19&&s<29)openAscendantCrate(p,s-19);else if(page==4&&s>=20&&s<26)openExtendedCrate(p,true,s-20);else if(page==5&&s>=19&&s<23)openExtendedCrate(p,true,6+s-19);}}
 private int page(String title){try{return Integer.parseInt(ChatColor.stripColor(title).replaceAll(".* • ","").split("/")[0]);}catch(Exception e){return 1;}}
 private void nav(Inventory i,int page,int max){if(page>1)i.setItem(45,b(Material.ARROW,ChatColor.YELLOW+"Previous Page",List.of(ChatColor.GRAY+"Page "+(page-1))));i.setItem(49,b(Material.BOOK,ChatColor.GOLD+"Page "+page+" / "+max,List.of(ChatColor.GRAY+"Organized weakest → strongest")));if(page<max)i.setItem(53,b(Material.ARROW,ChatColor.YELLOW+"Next Page",List.of(ChatColor.GRAY+"Page "+(page+1))));}
 private String pretty(Material m){String z=m.name().toLowerCase(Locale.ROOT).replace('_',' ');return Character.toUpperCase(z.charAt(0))+z.substring(1);}
 private void shopBuy(Player p,int page,int n){Material[][] mats={{Material.COOKED_BEEF,Material.GOLDEN_CARROT,Material.BREAD,Material.COOKED_CHICKEN,Material.COOKED_PORKCHOP,Material.PUMPKIN_PIE,Material.HONEY_BOTTLE},{Material.OAK_LOG,Material.SPRUCE_LOG,Material.STONE,Material.COBBLESTONE,Material.GLASS,Material.BRICKS,Material.QUARTZ_BLOCK},{Material.COAL,Material.IRON_INGOT,Material.GOLD_INGOT,Material.REDSTONE,Material.LAPIS_LAZULI,Material.DIAMOND,Material.EMERALD},{Material.ENDER_PEARL,Material.BLAZE_ROD,Material.GHAST_TEAR,Material.SLIME_BALL,Material.PHANTOM_MEMBRANE,Material.EXPERIENCE_BOTTLE,Material.OBSIDIAN},{Material.GUNPOWDER,Material.STRING,Material.BONE,Material.ROTTEN_FLESH,Material.SPIDER_EYE,Material.LEATHER,Material.FEATHER},{Material.TOTEM_OF_UNDYING,Material.NETHERITE_SCRAP,Material.ENCHANTED_GOLDEN_APPLE,Material.ELYTRA,Material.SHULKER_SHELL,Material.HEART_OF_THE_SEA,Material.NAUTILUS_SHELL}};int[][] amounts={{16,16,16,16,16,8,8},{32,32,64,64,32,32,16},{16,8,8,32,32,1,4},{8,4,2,16,4,16,16},{32,32,32,32,16,16,32},{1,1,1,1,2,1,8}};long[][] prices={{120,180,80,120,140,160,180},{160,180,120,100,300,350,500},{180,240,300,160,180,500,450},{600,800,900,400,700,450,500},{250,180,180,120,200,240,180},{12000,5000,25000,30000,4000,3500,1600}};if(page<1||page>20||n<0||n>6)return;buy(p,new ItemStack(shopMaterial(page,n),shopAmount(page,n)),shopPrice(page,n));}
 private static final Material[][] SHOP={ {Material.COOKED_BEEF,Material.GOLDEN_CARROT,Material.BREAD,Material.COOKED_CHICKEN,Material.COOKED_PORKCHOP,Material.PUMPKIN_PIE,Material.HONEY_BOTTLE},{Material.OAK_LOG,Material.SPRUCE_LOG,Material.STONE,Material.COBBLESTONE,Material.GLASS,Material.BRICKS,Material.QUARTZ_BLOCK},{Material.COAL,Material.IRON_INGOT,Material.GOLD_INGOT,Material.REDSTONE,Material.LAPIS_LAZULI,Material.DIAMOND,Material.EMERALD},{Material.ENDER_PEARL,Material.BLAZE_ROD,Material.GHAST_TEAR,Material.SLIME_BALL,Material.PHANTOM_MEMBRANE,Material.EXPERIENCE_BOTTLE,Material.OBSIDIAN},{Material.GUNPOWDER,Material.STRING,Material.BONE,Material.ROTTEN_FLESH,Material.SPIDER_EYE,Material.LEATHER,Material.FEATHER},{Material.TOTEM_OF_UNDYING,Material.NETHERITE_SCRAP,Material.ENCHANTED_GOLDEN_APPLE,Material.ELYTRA,Material.SHULKER_SHELL,Material.HEART_OF_THE_SEA,Material.NAUTILUS_SHELL},{Material.BIRCH_LOG,Material.JUNGLE_LOG,Material.ACACIA_LOG,Material.DARK_OAK_LOG,Material.MANGROVE_LOG,Material.CHERRY_LOG,Material.BAMBOO_BLOCK},{Material.REPEATER,Material.COMPARATOR,Material.PISTON,Material.STICKY_PISTON,Material.OBSERVER,Material.HOPPER,Material.DISPENSER},{Material.NETHERRACK,Material.SOUL_SAND,Material.SOUL_SOIL,Material.BLACKSTONE,Material.BASALT,Material.GLOWSTONE,Material.NETHER_WART},{Material.END_STONE,Material.PURPUR_BLOCK,Material.CHORUS_FRUIT,Material.POPPED_CHORUS_FRUIT,Material.END_ROD,Material.DRAGON_BREATH,Material.ENDER_EYE},{Material.GLASS_BOTTLE,Material.BREWING_STAND,Material.GLISTERING_MELON_SLICE,Material.MAGMA_CREAM,Material.FERMENTED_SPIDER_EYE,Material.SUGAR,Material.RABBIT_FOOT},{Material.WHITE_WOOL,Material.TERRACOTTA,Material.WHITE_CONCRETE,Material.SEA_LANTERN,Material.LANTERN,Material.CHAIN,Material.FLOWER_POT},{Material.GRANITE,Material.DIORITE,Material.ANDESITE,Material.DEEPSLATE,Material.TUFF,Material.CALCITE,Material.DRIPSTONE_BLOCK},{Material.RED_WOOL,Material.BLUE_WOOL,Material.GREEN_WOOL,Material.BLACK_WOOL,Material.RED_CONCRETE,Material.BLUE_CONCRETE,Material.BLACK_CONCRETE},{Material.PRISMARINE,Material.PRISMARINE_BRICKS,Material.DARK_PRISMARINE,Material.SPONGE,Material.KELP,Material.SEA_PICKLE,Material.SCUTE},{Material.DIRT,Material.GRASS_BLOCK,Material.MOSS_BLOCK,Material.ROOTED_DIRT,Material.MUD,Material.CLAY,Material.BONE_MEAL},{Material.TORCH,Material.SOUL_TORCH,Material.LANTERN,Material.SOUL_LANTERN,Material.GLOWSTONE,Material.SHROOMLIGHT,Material.SEA_LANTERN},{Material.RAIL,Material.POWERED_RAIL,Material.DETECTOR_RAIL,Material.ACTIVATOR_RAIL,Material.MINECART,Material.SADDLE,Material.LEAD},{Material.CRAFTING_TABLE,Material.FURNACE,Material.BLAST_FURNACE,Material.SMOKER,Material.ANVIL,Material.ENDER_CHEST,Material.BARREL},{Material.NAME_TAG,Material.CLOCK,Material.COMPASS,Material.SPYGLASS,Material.RECOVERY_COMPASS,Material.MUSIC_DISC_13,Material.DISC_FRAGMENT_5} };
 private Material shopMaterial(int p,int n){return SHOP[p-1][n];} private int shopAmount(int p,int n){return p==6?1:(p>=7?16: new int[][]{{16,16,16,16,16,8,8},{32,32,64,64,32,32,16},{16,8,8,32,32,1,4},{8,4,2,16,4,16,16},{32,32,32,32,16,16,32}}[p-1][n]);} private long shopPrice(int p,int n){if(p<=6){long[][] q={{120,180,80,120,140,160,180},{160,180,120,100,300,350,500},{180,240,300,160,180,500,450},{600,800,900,400,700,450,500},{250,180,180,120,200,240,180},{12000,5000,25000,30000,4000,3500,1600}};return q[p-1][n];}return 200L+(p-6)*125L+n*40L;}
 private void buy(Player p,ItemStack item,long price){try{if(!data.withdraw(p,price)){p.sendMessage(ChatColor.RED+"Not enough ESN Coins.");return;}HashMap<Integer,ItemStack> left=p.getInventory().addItem(item);if(!left.isEmpty()){data.deposit(p,price);p.sendMessage(ChatColor.RED+"Inventory full. Purchase refunded.");return;}p.sendMessage(ChatColor.GREEN+"Purchased for "+price+" ESN Coins.");}catch(Exception x){p.sendMessage(ChatColor.RED+"Purchase failed safely.");}}
 private void openCrate(Player p){int slot=findKey(p);if(slot<0){p.sendMessage(ChatColor.RED+"You need an ESN Crate Key.");return;}ItemStack k=p.getInventory().getItem(slot);if(k.getAmount()==1)p.getInventory().setItem(slot,null);else k.setAmount(k.getAmount()-1);ItemStack reward=reward();HashMap<Integer,ItemStack> left=p.getInventory().addItem(reward);if(!left.isEmpty())p.getWorld().dropItemNaturally(p.getLocation(),reward);p.sendMessage(ChatColor.GOLD+"Crate reward: "+reward.getAmount()+"x "+reward.getType().name());}
 private int findKey(Player p){for(int i=0;i<p.getInventory().getSize();i++){ItemStack x=p.getInventory().getItem(i);if(x!=null&&x.getType()==Material.TRIPWIRE_HOOK&&x.hasItemMeta()&&(ChatColor.GOLD+"ESN Crate Key").equals(x.getItemMeta().getDisplayName()))return i;}return -1;}
 private ItemStack reward(){int r=new Random().nextInt(100);if(r<2)return CustomItems.titanBlade();if(r<4)return CustomItems.voidPick();if(r<5)return CustomItems.titanChestplate();if(r<6)return CustomItems.voidHelmet();if(r<10)return new ItemStack(Material.NETHERITE_INGOT);if(r<20)return new ItemStack(Material.DIAMOND,3);if(r<50)return new ItemStack(Material.GOLDEN_APPLE,2);return new ItemStack(Material.EXPERIENCE_BOTTLE,16);}
 private void openTierCrate(Player p,int slot){int kslot=slot==25?findNamedKey(p,ChatColor.DARK_PURPLE+"Abyssal Crate Key"):slot==26?findNamedKey(p,ChatColor.DARK_RED+"Dragonlord Crate Key"):findKey(p);if(kslot<0){p.sendMessage(ChatColor.RED+"You need the correct crate key.");return;}ItemStack k=p.getInventory().getItem(kslot);if(k.getAmount()==1)p.getInventory().setItem(kslot,null);else k.setAmount(k.getAmount()-1);ItemStack[] pool=switch(slot){case 20->new ItemStack[]{CustomItems.infernalBlade(),CustomItems.infernalAxe(),CustomItems.infernalPick(),CustomItems.infernalHelmet(),CustomItems.infernalChest(),CustomItems.infernalLegs(),CustomItems.infernalBoots()};case 21->new ItemStack[]{CustomItems.stormBlade(),CustomItems.stormAxe(),CustomItems.stormPick(),CustomItems.stormHelmet(),CustomItems.stormChest(),CustomItems.stormLegs(),CustomItems.stormBoots()};case 22->new ItemStack[]{CustomItems.shadowBlade(),CustomItems.shadowAxe(),CustomItems.shadowPick(),CustomItems.shadowHelmet(),CustomItems.shadowChest(),CustomItems.shadowLegs(),CustomItems.shadowBoots()};case 23->new ItemStack[]{CustomItems.frostBlade(),CustomItems.frostAxe(),CustomItems.frostPick(),CustomItems.oceanTrident()};case 24->new ItemStack[]{CustomItems.solarBlade(),CustomItems.solarAxe(),CustomItems.solarPick(),CustomItems.solarHelmet(),CustomItems.solarChest(),CustomItems.solarLegs(),CustomItems.solarBoots()};case 25->new ItemStack[]{CustomItems.abyssBlade(),CustomItems.abyssAxe(),CustomItems.abyssPick(),CustomItems.abyssHelmet(),CustomItems.abyssChest(),CustomItems.abyssLegs(),CustomItems.abyssBoots()};default->new ItemStack[]{CustomItems.dragonBlade(),CustomItems.dragonAxe(),CustomItems.dragonHelmet(),CustomItems.dragonChest(),CustomItems.dragonLegs(),CustomItems.dragonBoots()};};ItemStack reward=pool[new Random().nextInt(pool.length)];HashMap<Integer,ItemStack> left=p.getInventory().addItem(reward);if(!left.isEmpty())p.getWorld().dropItemNaturally(p.getLocation(),reward);p.sendMessage(ChatColor.GOLD+"Crate reward: "+reward.getItemMeta().getDisplayName());}

 private void openExtendedCrate(Player p,boolean high,int tier){int slot=-1;for(int n=0;n<p.getInventory().getSize();n++)if(ExtendedCrates.isKey(p.getInventory().getItem(n),high,tier)){slot=n;break;}if(slot<0){p.sendMessage(ChatColor.RED+"You need a "+(high?ExtendedCrates.HIGH[tier]:ExtendedCrates.LOW[tier])+" Crate Key.");return;}ItemStack k=p.getInventory().getItem(slot);if(k.getAmount()==1)p.getInventory().setItem(slot,null);else k.setAmount(k.getAmount()-1);ItemStack[] pool=ExtendedCrates.pool(high,tier);ItemStack reward=pool[new Random().nextInt(pool.length)];Map<Integer,ItemStack> left=p.getInventory().addItem(reward);left.values().forEach(z->p.getWorld().dropItemNaturally(p.getLocation(),z));p.sendMessage((high?ChatColor.LIGHT_PURPLE:ChatColor.GREEN)+"Crate reward: "+reward.getItemMeta().getDisplayName());}
 private void openAscendantCrate(Player p,int tier){int slot=-1;for(int n=0;n<p.getInventory().getSize();n++)if(MythicCrates.isKey(p.getInventory().getItem(n),tier)){slot=n;break;}if(slot<0){p.sendMessage(ChatColor.RED+"You need a "+MythicCrates.TIERS[tier]+" Crate Key.");return;}ItemStack k=p.getInventory().getItem(slot);if(k.getAmount()==1)p.getInventory().setItem(slot,null);else k.setAmount(k.getAmount()-1);ItemStack[] pool=MythicCrates.pool(tier);ItemStack reward=pool[new Random().nextInt(pool.length)];Map<Integer,ItemStack> left=p.getInventory().addItem(reward);left.values().forEach(z->p.getWorld().dropItemNaturally(p.getLocation(),z));p.sendMessage(ChatColor.GOLD+"ASCENDANT reward: "+reward.getItemMeta().getDisplayName());}
 private void openEternalCrate(Player p){int slot=-1;for(int n=0;n<p.getInventory().getSize();n++)if(EternalGear.key(p.getInventory().getItem(n))){slot=n;break;}if(slot<0){p.sendMessage(ChatColor.RED+"You need an Eternal Crate Key.");return;}ItemStack k=p.getInventory().getItem(slot);if(k.getAmount()==1)p.getInventory().setItem(slot,null);else k.setAmount(k.getAmount()-1);ItemStack[] pool=EternalGear.pool();ItemStack reward=pool[new Random().nextInt(pool.length)];HashMap<Integer,ItemStack> left=p.getInventory().addItem(reward);left.values().forEach(z->p.getWorld().dropItemNaturally(p.getLocation(),z));p.sendMessage(ChatColor.DARK_AQUA+"ETERNAL reward: "+reward.getItemMeta().getDisplayName());}

 private void openCelestialCrate(Player p){int slot=findKey(p);if(slot<0){p.sendMessage(ChatColor.RED+"You need an ESN Crate Key.");return;}ItemStack k=p.getInventory().getItem(slot);if(k.getAmount()==1)p.getInventory().setItem(slot,null);else k.setAmount(k.getAmount()-1);ItemStack[] pool={CustomItems.celestialBlade(),CustomItems.celestialAxe(),CustomItems.celestialPick(),CustomItems.celestialHelmet(),CustomItems.celestialChest(),CustomItems.celestialLegs(),CustomItems.celestialBoots(),CustomItems.celestialBow(),CustomItems.reaperScythe(),CustomItems.oceanTrident(),CustomItems.dragonBow(),CustomItems.phantomCrossbow()};ItemStack reward=pool[new Random().nextInt(pool.length)];HashMap<Integer,ItemStack> left=p.getInventory().addItem(reward);if(!left.isEmpty())p.getWorld().dropItemNaturally(p.getLocation(),reward);p.sendMessage(ChatColor.AQUA+"Celestial reward: "+reward.getItemMeta().getDisplayName());}
 public ItemStack key(){return LootDrops.key();}
 private void daily(Player p){try{long wait=data.claimDaily(p);if(wait==0){p.getInventory().addItem(key());p.sendMessage(ChatColor.GREEN+"Daily claimed: 250 Coins + 1 ESN Crate Key!");}else p.sendMessage(ChatColor.YELLOW+"Daily available in "+((wait+3599999)/3600000)+"h.");}catch(Exception x){p.sendMessage(ChatColor.RED+"Daily reward unavailable.");}}
 private void quests(Player p){int m=mined.getOrDefault(p.getUniqueId(),0),k=kills.getOrDefault(p.getUniqueId(),0);p.sendMessage(ChatColor.AQUA+"Daily Quests: "+m+"/64 blocks mined | "+k+"/10 hostile mobs defeated");}
 private void leaderboard(Player p){try{p.sendMessage(ChatColor.GOLD+"--- ESN Richest Players ---");int n=1;for(var e:data.topBalances(10))p.sendMessage(ChatColor.YELLOW.toString()+(n++)+". "+e.playerName()+" - "+e.balance()+" Coins");}catch(Exception x){p.sendMessage(ChatColor.RED+"Leaderboard unavailable.");}}
 private void warps(Player p){p.sendMessage(ChatColor.YELLOW+"Warps: "+ChatColor.WHITE+"/spawn "+ChatColor.GRAY+"• Survival exploration begins outside the protected spawn.");}
 @EventHandler public void mine(BlockBreakEvent e){mined.merge(e.getPlayer().getUniqueId(),1,Integer::sum);}
 @EventHandler public void death(EntityDeathEvent e){if(e.getEntity().getKiller()!=null)kills.merge(e.getEntity().getKiller().getUniqueId(),1,Integer::sum);}
 private List<String> crateLore(String chance,String... rewards){List<String> lore=new ArrayList<>();lore.add(ChatColor.GRAY+"Requires: ESN Crate Key");lore.add(ChatColor.YELLOW+"Click to open");lore.add(ChatColor.DARK_GRAY+"--- Possible Rewards ---");for(String reward:rewards)lore.add(ChatColor.AQUA+chance+ChatColor.GRAY+" - "+ChatColor.WHITE+reward);return lore;}
 
 private int findNamedKey(Player p,String name){for(int i=0;i<p.getInventory().getSize();i++){ItemStack x=p.getInventory().getItem(i);if(x!=null&&x.hasItemMeta()&&name.equals(x.getItemMeta().getDisplayName()))return i;}return -1;}
 
 private List<String> crateLoreKey(String key,String chance,String... rewards){List<String> lore=new ArrayList<>();lore.add(ChatColor.GRAY+"Requires: "+key);lore.add(ChatColor.YELLOW+"Click to open");lore.add(ChatColor.DARK_GRAY+"--- Possible Rewards ---");for(String reward:rewards)lore.add(ChatColor.AQUA+chance+ChatColor.GRAY+" - "+ChatColor.WHITE+reward);return lore;}
 
 private ItemStack b(Material m,String n){return b(m,n,List.of());}private ItemStack b(Material m,String n,List<String> lore){ItemStack x=new ItemStack(m);ItemMeta im=x.getItemMeta();im.setDisplayName(n);im.setLore(lore);x.setItemMeta(im);return x;}
}
